  result['captures'].append(dict(side=r['side'],tier=r['tier'],maximum=m,durationMs=f['durationMs'],firstChargeCompleteMs=complete,buildsNearMaximum=[x for x in f['builds']if abs(x['at']-m['at'])<300],rawSource=str(path),rawSha256=hashlib.sha256(path.read_bytes()).hexdigest()))
