 r=read(p)[0];f=r['performance'];m=peak(r);origin=f['timeOrigin']+f['startedAt'];commands=[dict(x,startMs=x['beforeWall']-origin,endMs=x['afterWall']-origin)for x in r['cleanupCommands']]
 result['diagnostic']=dict(diagnostic=r['diagnostic'],seconds=r['seconds'],side=r['side'],tier=r['tier'],maximum=m,longTasks=f['longTasks'],cleanupCommands=commands,stopRequestMs=r['stopRequestedWall']-origin,maximumOverlapsCleanup=any(x['startMs']<=m['at']and x['endMs']>=m['at']-m['ms']for x in commands),rawSource=str(p),rawSha256=hashlib.sha256(p.read_bytes()).hexdigest())
